1	import {
2	  type AdvancedIMessage,
3	  type CatchUpEvent,
4	  type GroupEvent,
5	  type MessageEvent,
6	  type PollEvent,
7	  type SingleServiceAddressInfo,
8	  ValidationError,
9	} from "@photon-ai/advanced-imessage/grpc";
10	import { sanitizePhone } from "@photon-ai/otel";
11	import {
12	  type ManagedStream,
13	  mergeStreams,
14	  type ProjectData,
15	} from "@spectrum-ts/core";
16	import {
17	  type CloseableAsyncIterable,
18	  createLogger,
19	  errorAttrs,
20	  type ResumableStreamItem,
21	  resumableOrderedStream,
22	} from "@spectrum-ts/core/authoring";
23	import { getCloudRecover } from "../auth";
24	import { getMessageCache, getPollCache, type PollCache } from "../cache";
25	import {
26	  type IMessageMessage,
27	  type RemoteClient,
28	  SHARED_PHONE,
29	} from "../types";
30	import { isSharedMode } from "./client";
31	import {
32	  type ContactShareTracker,
33	  getContactShareTracker,
34	} from "./contact-share";
35	import {
36	  groupEventActor,
37	  groupEventMessageId,
38	  toGroupEventMessages,
39	} from "./group-events";
40	import { toInboundMessages } from "./inbound";
41	import { cachePollEvent, toPollDeltaMessages } from "./polls";
42	import type { ProfileSyncGate } from "./profile-sync-gate";
43	import { toReactionMessages } from "./reactions";
44	import { readReceiptMessageId, toReadReceiptMessages } from "./read-receipts";
45	
46	// The proxy rejects an unknown/pruned resume cursor with INVALID_ARGUMENT,
47	// which the client surfaces as ValidationError — the only ValidationError the
48	// catch-up RPC produces (ENG-1566).
49	const isCursorRejectedIMessageError = (error: unknown): boolean =>
50	  error instanceof ValidationError;
51	
52	const streamLabel = (
53	  kind: "messages" | "polls" | "groups",
54	  phone: string
55	): string =>
56	  `imessage.${kind}:${phone === SHARED_PHONE ? phone : sanitizePhone(phone)}`;
57	
58	// The acting party's identity, without the `isFromMe` half. Split out because
59	// `message.read`'s `isFromMe` is undocumented and most plausibly describes the
60	// *underlying message* — ours, for a genuine receipt — so trusting it there
61	// would suppress every receipt worth surfacing. Vacuous in shared mode: the
62	// sentinel never matches a real address.
63	const isActorCurrentAccount = (
64	  actor: SingleServiceAddressInfo | undefined,
65	  phone: string
66	): boolean =>
67	  phone !== SHARED_PHONE &&
68	  actor?.address !== undefined &&
69	  actor.address === phone;
70	
71	const isEventFromCurrentAccount = (
72	  event: Pick<MessageEvent | PollEvent | GroupEvent, "actor" | "isFromMe">,
73	  phone: string
74	): boolean => event.isFromMe || isActorCurrentAccount(event.actor, phone);
75	
76	const streamLog = createLogger("spectrum.imessage.stream");
77	
78	// Mapping does RPC work (message/attachment rebuilds), so its errors split
79	// two ways. Client errors marked `retryable` are transient (network blip,
80	// gateway restart): rethrow so resumableOrderedStream refetches the event
81	// via catch-up and the message is delivered late rather than lost.
82	const isRetryableMappingError = (error: unknown): boolean =>
83	  typeof error === "object" &&
84	  error !== null &&
85	  (error as { retryable?: unknown }).retryable === true;
86	
87	// Everything else is deterministic (schema/shape throws, non-retryable
88	// client errors) and must not wedge the stream: retrying would refetch the
89	// same poison event forever and the cursor would never advance. Convert the
90	// throw into an empty skip item — the same shape the isFromMe skips use —
91	// so the cursor moves past the event.
92	const skipUnmappable = async <T>(
93	  label: string,
94	  cursor: string,
95	  map: () => Promise<ResumableStreamItem<T>>
96	): Promise<ResumableStreamItem<T>> => {
97	  try {
98	    return await map();
99	  } catch (error) {
100	    if (isRetryableMappingError(error)) {
101	      throw error;
102	    }
103	    streamLog.warn(
104	      "skipping unmappable imessage event",
105	      {
106	        "spectrum.imessage.stream": label,
107	        "spectrum.imessage.cursor": cursor,
108	        ...errorAttrs(error),
109	      },
110	      error instanceof Error ? error : undefined
111	    );
112	    return { cursor, id: `unmappable:${cursor}`, values: [] };
113	  }
114	};
115	
116	/**
117	 * Side effect fired when a non-self `message.received` event is converted.
118	 * Receives the `chatGuid` of the inbound message. Implementations must be
119	 * synchronous and never throw — typical use is fire-and-forget cache lookup
120	 * + background API call.
121	 */
122	type OnInboundMessage = (chatGuid: string) => void;
123	
124	const toMessageItem = async (
125	  client: AdvancedIMessage,
126	  event: MessageEvent,
127	  phone: string,
128	  cursor: string,
129	  onInbound?: OnInboundMessage
130	): Promise<ResumableStreamItem<IMessageMessage>> => {
131	  if (event.type === "message.received") {
132	    if (event.message.isFromMe) {
133	      return { cursor, id: event.message.guid, values: [] };
134	    }
135	
136	    const cache = getMessageCache(client);
137	    const values = await toInboundMessages(client, cache, event, phone);
138	
139	    // After conversion succeeds — an event skipUnmappable discards must not
140	    // trigger a contact-card share (and burn its 24h dedupe slot) for a
141	    // message that was never delivered.
142	    const inboundChatGuid = event.message.chatGuids?.[0];
143	    if (inboundChatGuid) {
144	      onInbound?.(inboundChatGuid);
145	    }
146	
147	    return { cursor, id: event.message.guid, values };
148	  }
149	
150	  if (event.type === "message.reactionAdded") {
151	    if (isEventFromCurrentAccount(event, phone)) {
152	      return {
153	        cursor,
154	        id: `${event.messageGuid}:reaction:${event.sequence}`,
155	        values: [],
156	      };
157	    }
158	
159	    const cache = getMessageCache(client);
160	    return {
161	      cursor,
162	      id: `${event.messageGuid}:reaction:${event.sequence}`,
163	      values: await toReactionMessages(client, cache, event, phone),
164	    };
165	  }
166	
167	  if (event.type === "message.read") {
168	    const id = readReceiptMessageId(event);
169	    // Logged before any filtering: if this never fires, the upstream stream is
170	    // not delivering `message.read` at all and nothing downstream can be at
171	    // fault. Every drop below logs its own reason.
172	    streamLog.debug("received a read event", {
173	      "spectrum.imessage.read.message_guid": event.messageGuid,
174	      "spectrum.imessage.read.sequence": event.sequence,
175	      "spectrum.imessage.read.chat_guid": event.chatGuid,
176	      "spectrum.imessage.read.actor": event.actor?.address
177	        ? sanitizePhone(event.actor.address)
178	        : "none",
179	      "spectrum.imessage.read.is_from_me": event.isFromMe,
180	      "spectrum.imessage.read.line": phone,
181	    });
182	    // No actor-based self-check here, unlike reactions. Verified against a
183	    // live line: on this arm `actor` is *our own* line's address even when the
184	    // peer is the one who read, so `isEventFromCurrentAccount` (or its actor
185	    // half) would suppress every genuine receipt. `isFromMe` is no better —
186	    // it came back `false` for a peer read, the opposite of the reaction arm.
187	    //
188	    // Self-suppression is instead carried entirely by `toReadReceiptMessages`,
189	    // which requires the resolved target to be one of *our* outbound messages.
190	    // That holds regardless of what `actor`/`isFromMe` mean: our own
191	    // `chats.markRead()` marks *their* inbound messages, so its echo resolves
192	    // to an inbound target and is dropped.
193	    const cache = getMessageCache(client);
194	    return {
195	      cursor,
196	      id,
197	      values: await toReadReceiptMessages(client, cache, event, phone),
198	    };
199	  }
200	
201	  // Consumed for the cursor but not surfaced (edits, unsends, sticker
202	  // placements, reaction removals). Logged so "the stream is alive but this
203	  // event type never arrives" is distinguishable from "the stream is dead".
204	  streamLog.debug("message event consumed without mapping", {
205	    "spectrum.imessage.event_type": event.type,
206	    "spectrum.imessage.sequence": event.sequence,
207	  });
208	
209	  return {
210	    cursor,
211	    id: `${event.type}:${"messageGuid" in event ? event.messageGuid : "unknown"}:${event.sequence}`,
212	    values: [],
213	  };
214	};
215	
216	const toPollItem = async (
217	  client: AdvancedIMessage,
218	  pollCache: PollCache,
219	  event: PollEvent,
220	  phone: string,
221	  cursor: string
222	): Promise<ResumableStreamItem<IMessageMessage>> => {
223	  cachePollEvent(pollCache, event);
224	  if (isEventFromCurrentAccount(event, phone)) {
225	    return {
226	      cursor,
227	      id: `${event.pollMessageGuid}:poll:${event.sequence}`,
228	      values: [],
229	    };
230	  }
231	
232	  return {
233	    cursor,
234	    id: `${event.pollMessageGuid}:poll:${event.sequence}`,
235	    values: await toPollDeltaMessages(client, pollCache, event, phone),
236	  };
237	};
238	
239	const toGroupItem = async (
240	  client: AdvancedIMessage,
241	  event: GroupEvent,
242	  phone: string,
243	  cursor: string
244	): Promise<ResumableStreamItem<IMessageMessage>> => {
245	  const id = groupEventMessageId(event);
246	  // Self-check against the acting party — for a leave that is the leaver
247	  // (`event.actor` is often absent there), so the agent's own departure via
248	  // `space.leave()` doesn't echo back as an inbound event.
249	  const actor = groupEventActor(event);
250	  if (isEventFromCurrentAccount({ actor, isFromMe: event.isFromMe }, phone)) {
251	    return { cursor, id, values: [] };
252	  }
253	
254	  return {
255	    cursor,
256	    id,
257	    values: await toGroupEventMessages(client, event, phone),
258	  };
259	};
260	
261	const toCatchUpCompleteItem = (
262	  event: Extract<CatchUpEvent, { type: "catchup.complete" }>
263	): ResumableStreamItem<IMessageMessage> => ({
264	  cursor: String(event.headSequence),
265	  id: `${event.type}:${event.headSequence}`,
266	  values: [],
267	});
268	
269	type CatchUpCompleteEvent = Extract<CatchUpEvent, { type: "catchup.complete" }>;
270	type MessageCatchUpEvent = MessageEvent | CatchUpCompleteEvent;
271	type PollCatchUpEvent = PollEvent | CatchUpCompleteEvent;
272	type GroupCatchUpEvent = GroupEvent | CatchUpCompleteEvent;
273	
274	const isMessageEvent = (event: CatchUpEvent): event is MessageEvent =>
275	  event.type.startsWith("message.");
276	
277	const isPollEvent = (event: CatchUpEvent): event is PollEvent =>
278	  event.type === "poll.changed";
279	
280	const isGroupEvent = (event: CatchUpEvent): event is GroupEvent =>
281	  event.type === "group.changed";
282	
283	async function* catchUpEvents<T extends MessageEvent | PollEvent | GroupEvent>(
284	  client: AdvancedIMessage,
285	  cursor: string,
286	  isWanted: (event: CatchUpEvent) => event is T
287	): AsyncGenerator<T | CatchUpCompleteEvent> {
288	  const since = toResumeAfter(cursor);
289	  if (since === undefined) {
290	    return;
291	  }
292	
293	  for await (const event of client.events.catchUp(since)) {
294	    if (event.type === "catchup.complete") {
295	      yield event;
296	      return;
297	    }
298	    if (isWanted(event)) {
299	      yield event;
300	    }
301	  }
302	}
303	
304	const toResumeAfter = (cursor: string | undefined): number | undefined => {
305	  if (!cursor) {
306	    return;
307	  }
308	  const sequence = Number(cursor);
309	  return Number.isSafeInteger(sequence) && sequence >= 0 ? sequence : undefined;
310	};
311	
312	async function* afterCursor(
313	  stream: CloseableAsyncIterable<MessageEvent | PollEvent | GroupEvent>,
314	  cursor?: string
315	): AsyncGenerator<MessageEvent | PollEvent | GroupEvent> {
316	  const resumeAfter = toResumeAfter(cursor);
317	  try {
318	    for await (const event of stream) {
319	      if (resumeAfter !== undefined && event.sequence <= resumeAfter) {
320	        continue;
321	      }
322	      yield event;
323	    }
324	  } finally {
325	    await stream.close?.();
326	  }
327	}
328	
329	const withClose = <T extends MessageEvent | PollEvent | GroupEvent>(
330	  source: CloseableAsyncIterable<T>,
331	  cursor?: string
332	): CloseableAsyncIterable<T> =>
333	  Object.assign(afterCursor(source, cursor) as AsyncGenerator<T>, {
334	    close: async () => {
335	      await source.close?.();
336	    },
337	  });
338	
339	const messageStream = (
340	  client: AdvancedIMessage,
341	  phone: string,
342	  onInbound?: OnInboundMessage,
343	  recover?: () => Promise<void>
344	): ManagedStream<IMessageMessage> =>
345	  resumableOrderedStream<MessageEvent, MessageCatchUpEvent, IMessageMessage>({
346	    fetchMissed: (cursor) => catchUpEvents(client, cursor, isMessageEvent),
347	    isCursorRejectedError: isCursorRejectedIMessageError,
348	    label: streamLabel("messages", phone),
349	    recover,
350	    processLive: (event) =>
351	      skipUnmappable(
352	        streamLabel("messages", phone),
353	        String(event.sequence),
354	        () =>
355	          toMessageItem(client, event, phone, String(event.sequence), onInbound)
356	      ),
357	    processMissed: (event) =>
358	      event.type === "catchup.complete"
359	        ? Promise.resolve(toCatchUpCompleteItem(event))
360	        : skipUnmappable(
361	            streamLabel("messages", phone),
362	            String(event.sequence),
363	            () =>
364	              toMessageItem(
365	                client,
366	                event,
367	                phone,
368	                String(event.sequence),
369	                onInbound
370	              )
371	          ),
372	    subscribeLive: (cursor) =>
373	      withClose(client.messages.subscribeEvents(), cursor),
374	  });
375	
376	const pollStream = (
377	  client: AdvancedIMessage,
378	  pollCache: PollCache,
379	  phone: string,
380	  recover?: () => Promise<void>
381	): ManagedStream<IMessageMessage> =>
382	  resumableOrderedStream<PollEvent, PollCatchUpEvent, IMessageMessage>({
383	    fetchMissed: (cursor) => catchUpEvents(client, cursor, isPollEvent),
384	    isCursorRejectedError: isCursorRejectedIMessageError,
385	    label: streamLabel("polls", phone),
386	    recover,
387	    processLive: (event) =>
388	      skipUnmappable(streamLabel("polls", phone), String(event.sequence), () =>
389	        toPollItem(client, pollCache, event, phone, String(event.sequence))
390	      ),
391	    processMissed: (event) =>
392	      event.type === "catchup.complete"
393	        ? Promise.resolve(toCatchUpCompleteItem(event))
394	        : skipUnmappable(
395	            streamLabel("polls", phone),
396	            String(event.sequence),
397	            () =>
398	              toPollItem(
399	                client,
400	                pollCache,
401	                event,
402	                phone,
403	                String(event.sequence)
404	              )
405	          ),
406	    subscribeLive: (cursor) =>
407	      withClose(client.polls.subscribeEvents(), cursor),
408	  });
409	
410	const groupStream = (
411	  client: AdvancedIMessage,
412	  phone: string,
413	  recover?: () => Promise<void>
414	): ManagedStream<IMessageMessage> =>
415	  resumableOrderedStream<GroupEvent, GroupCatchUpEvent, IMessageMessage>({
416	    fetchMissed: (cursor) => catchUpEvents(client, cursor, isGroupEvent),
417	    isCursorRejectedError: isCursorRejectedIMessageError,
418	    label: streamLabel("groups", phone),
419	    recover,
420	    processLive: (event) =>
421	      skipUnmappable(streamLabel("groups", phone), String(event.sequence), () =>
422	        toGroupItem(client, event, phone, String(event.sequence))
423	      ),
424	    processMissed: (event) =>
425	      event.type === "catchup.complete"
426	        ? Promise.resolve(toCatchUpCompleteItem(event))
427	        : skipUnmappable(
428	            streamLabel("groups", phone),
429	            String(event.sequence),
430	            () => toGroupItem(client, event, phone, String(event.sequence))
431	          ),
432	    subscribeLive: (cursor) =>
433	      withClose(client.groups.subscribeEvents(), cursor),
434	  });
435	
436	const clientStream = (
437	  client: AdvancedIMessage,
438	  pollCache: PollCache,
439	  phone: string,
440	  includeGroupEvents: boolean,
441	  onInbound?: OnInboundMessage,
442	  recover?: () => Promise<void>
443	): ManagedStream<IMessageMessage> => {
444	  const streams: ManagedStream<IMessageMessage>[] = [
445	    messageStream(client, phone, onInbound, recover),
446	    pollStream(client, pollCache, phone, recover),
447	  ];
448	
449	  if (includeGroupEvents) {
450	    streams.push(groupStream(client, phone, recover));
451	  }
452	
453	  return mergeStreams(streams);
454	};
455	
456	const shareWhenProfileSynced = (
457	  tracker: ContactShareTracker,
458	  gate: ProfileSyncGate,
459	  chatGuid: string
460	): void => {
461	  // The existing 24-hour Line + chat dedupe must run before the project-level
462	  // Cloud gate. Repeat inbound messages therefore stay entirely local.
463	  if (tracker.hasRecentlyShared(chatGuid)) {
464	    return;
465	  }
466	
467	  gate
468	    .isEnabled()
469	    .then((enabled) => {
470	      if (enabled) {
471	        // Multiple messages may have awaited the same coalesced gate refresh.
472	        // maybeShare sets its cache synchronously, so only the first continues
473	        // to the RPC.
474	        tracker.maybeShare(chatGuid);
475	      }
476	    })
477	    .catch((error: unknown) => {
478	      // ProfileSyncGate handles expected Cloud failures and returns false.
479	      // Keep this boundary defensive so a faulty gate can never break inbound
480	      // message processing or create an unhandled rejection.
481	      streamLog.warn(
482	        "profile sync gate failed; skipping automatic contact sharing",
483	        errorAttrs(error),
484	        error instanceof Error ? error : undefined
485	      );
486	    });
487	};
488	
489	const contactShareHandler = (
490	  tracker: ContactShareTracker,
491	  profileSyncGate?: ProfileSyncGate | undefined
492	): OnInboundMessage =>
493	  profileSyncGate
494	    ? (chatGuid) => shareWhenProfileSynced(tracker, profileSyncGate, chatGuid)
495	    : (chatGuid) => tracker.maybeShare(chatGuid);
496	
497	export const messages = (
498	  clients: RemoteClient[],
499	  projectConfig?: ProjectData | undefined,
500	  profileSyncGate?: ProfileSyncGate | undefined
501	): ManagedStream<IMessageMessage> => {
502	  const pollCache = getPollCache(clients);
503	  // Direct callers retain the initialization-snapshot behavior. Cloud-backed
504	  // Spectrum clients also provide a refreshable project-level gate, checked
505	  // only after the 24h per-Line/chat tracker says a share is eligible.
506	  const staticShareEnabled = projectConfig?.profile?.imessageSynced === true;
507	  // Cloud clients can re-mint a rejected token; explicit/static-token clients
508	  // return undefined (nothing to refresh). Shared across this client array's
509	  // streams so the message + poll loops coalesce onto one re-mint.
510	  const recover = getCloudRecover(clients);
511	  const includeGroupEvents = !isSharedMode(clients);
512	  return mergeStreams(
513	    clients.map((entry) => {
514	      const tracker =
515	        staticShareEnabled || profileSyncGate
516	          ? getContactShareTracker(entry.client)
517	          : undefined;
518	      return clientStream(
519	        entry.client,
520	        pollCache,
521	        entry.phone,
522	        includeGroupEvents,
523	        tracker ? contactShareHandler(tracker, profileSyncGate) : undefined,
524	        recover
525	      );
526	    })
527	  );
528	};
