  attach(client: WhatsAppClient): void;
  detach(client: WhatsAppClient): Promise<void> | void;
}

const observers = new WeakMap<WhatsAppClient[], Set<LineObserver>>();
const lineIds = new WeakMap<WhatsAppClient, string>();

let fallbackKeys = 0;

